<?php
namespace Modules\Cutting\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;use Modules\Core\Models\Concerns\BelongsToCompany;use Modules\MasterData\Models\ShadeGroup;
class Lay extends Model { use BelongsToCompany; public const STATUSES=['DRAFT','IN_PROGRESS','COMPLETED','CANCELLED']; protected $fillable=['company_id','cut_order_id','lay_no','layer_count','lay_date','shade_validation_enabled','shade_group_id','status','created_by','updated_by']; protected function casts():array{return['lay_date'=>'date','shade_validation_enabled'=>'boolean'];} public function cutOrder():BelongsTo{return $this->belongsTo(CutOrder::class);} public function shadeGroup():BelongsTo{return $this->belongsTo(ShadeGroup::class);} public function rolls():HasMany{return $this->hasMany(LayRoll::class);} public function cutOutputs():HasMany{return $this->hasMany(CutOutput::class);} public function overrideRequests():HasMany{return $this->hasMany(ShadeOverrideRequest::class);} }
